    fn scope_claim_renewal_and_decision_late_clock_refuse_before_publication() {
        use crate::WorkEnvironment;
        struct Clock {
            first: bool,
            initial: &'static str,
            publication: &'static str,
        }
        impl WorkEnvironment for Clock {
            fn identifier(&mut self, prefix: &str) -> Result<String, crate::RuntimeError> {
                crate::generate_identifier(prefix)
            }
            fn timestamp(&mut self) -> Result<String, crate::RuntimeError> {
                let value = if self.first {
                    self.initial
                } else {
                    self.publication
                };
                self.first = false;
                Ok(value.into())
            }
            fn operator(&mut self) -> Result<String, crate::RuntimeError> {
                crate::SystemEnvironment.operator()
            }
            fn git(&mut self, root: &Path) -> Result<crate::GitObservation, crate::RuntimeError> {
                crate::SystemEnvironment.git(root)
            }
        }
        for (clock, expired, decision_publication) in [
            ("2026-10-20T12:00:04Z", false, "2026-10-20T12:00:04Z"),
            ("2026-10-20T12:00:04Z", false, "2026-10-20T12:00:06Z"),
            ("2026-10-20T12:00:06Z", true, ""),
        ] {
            let f = Fixture::new();
            crate::RootStore::initialize(&f.root, &mut crate::SystemEnvironment)
                .unwrap()
                .close()
                .unwrap();
            let mut store = crate::RootStore::open(&f.root, true).unwrap();
            let created=store.execute_external("","work.create",&serde_json::to_vec(&serde_json::json!({"schema_version":1,"event_id":"clock-create","expected_revision":0,"title":"Clock witness","objective":"Observe lease publication","scope":"Owned fixture","criteria":["No expired publication"]})).unwrap(),&mut crate::SystemEnvironment).unwrap().result.work;
            let enabled=store.execute_external(&created.id,"planning.enable",&serde_json::to_vec(&serde_json::json!({"schema_version":1,"event_id":"clock-enable","expected_revision":created.revision,"max_activations":3,"max_tasks":3,"max_decisions":3})).unwrap(),&mut crate::SystemEnvironment).unwrap().result.work;
            let request = PlanningRequest {
                expected_revision: enabled.revision,
                ..f.request()
            };
            let before = store.read_work(&created.id).unwrap();
            let result = store.execute_external(
                &created.id,
                "planning.claim",
                &crate::encode_planning_request(&request).unwrap(),
                &mut Clock {
                    first: true,
                    initial: "2026-10-20T12:00:00Z",
                    publication: clock,
                },
            );
            let after = store.read_work(&created.id).unwrap();
            store.close().unwrap();
            // Read-only ledger observation distinguishes Work rollback from a
            // leaked financial reservation after late prepublication refusal.
            let db = rusqlite::Connection::open_with_flags(
                f.root.join(".swarm/state.db"),
                rusqlite::OpenFlags::SQLITE_OPEN_READ_ONLY,
            )
            .unwrap();
            let calls: i64 = db
                .query_row(
                    "SELECT count(*) FROM planning_calls WHERE work_id=?1",
                    [&created.id],
                    |r| r.get(0),
                )
                .unwrap();
            db.close().map_err(|(_, e)| e).unwrap();
            assert_eq!(
                calls,
                if expired { 0 } else { 1 },
                "Claim and financial reservation must commit or roll back together"
            );
            if expired {
                assert!(result.is_err(), "Expired claim was accepted");
                assert_eq!(
                    result.err().unwrap().code(),
                    "planning-claim-expired-before-publication"
                );
                assert_eq!(
                    after, before,
                    "Rejected claim must preserve Work and activation count"
                );
            } else {
                assert!(result.is_ok());
                assert_eq!(after.planning.as_ref().unwrap().activations, 1);
                let mut decision = PlanningRequest {
                    schema_version: 1,
                    event_id: "clock-decision".into(),
                    expected_revision: after.revision,
                    scope: "root".into(),
                    scope_revision: 1,
                    holder: request.holder.clone(),
                    generation: 1,
                    input_events: Some(vec!["clock-enable".into()]),
                    reason: "Observed clock boundary".into(),
                    ..Default::default()
                };
                let mut store = crate::RootStore::open(&f.root, true).unwrap();
                let lease_before = store.read_work(&created.id).unwrap();
                let renewal = PlanningRequest {
                    event_id: "clock-renew".into(),
                    expected_revision: lease_before.revision,
                    generation: 1,
                    ..request.clone()
                };
                let renewed = store.execute_external(
                    &created.id,
                    "planning.lease-renew",
                    &crate::encode_planning_request(&renewal).unwrap(),
                    &mut Clock {
                        first: true,
                        initial: "2026-10-20T12:00:04Z",
                        publication: decision_publication,
                    },
                );
                if decision_publication == "2026-10-20T12:00:06Z" {
                    assert_eq!(renewed.err().unwrap().code(), "stale_lease");
                    assert_eq!(store.read_work(&created.id).unwrap(), lease_before);
                } else {
                    let work = renewed.unwrap().result.work;
                    let p = work.planning.as_ref().unwrap();
                    assert_eq!(p.activations, 1);
                    assert_eq!(p.decisions, 0);
                    let scope = p
                        .scopes
                        .as_ref()
                        .unwrap()
                        .iter()
                        .find(|s| s.id == "root")
                        .unwrap();
                    assert_eq!(scope.generation, 1);
                    assert_eq!(scope.revision, 1);
                    assert_eq!(scope.lease_until, "2026-10-20T12:00:09Z");
                }
                decision.expected_revision = store.read_work(&created.id).unwrap().revision;
                let before = store.read_work(&created.id).unwrap();
                let result = store.execute_external(
                    &created.id,
                    "planning.decide",
                    &crate::encode_planning_request(&decision).unwrap(),
                    &mut Clock {
                        first: true,
                        initial: "2026-10-20T12:00:04Z",
                        publication: decision_publication,
                    },
                );
                if decision_publication == "2026-10-20T12:00:06Z" {
                    assert_eq!(result.err().unwrap().code(), "stale_lease");
                    assert_eq!(
                        store.read_work(&created.id).unwrap(),
                        before,
                        "Expired decision must preserve the complete recorded Work"
                    );
                    // Recover with a new public claim after expiry, preserving
                    // consumed activations and advancing clocks only forward.
                    let reclaimed = store
                        .execute_external(
                            &created.id,
                            "planning.claim",
                            &crate::encode_planning_request(&PlanningRequest {
                                event_id: "clock-reclaim".into(),
                                expected_revision: before.revision,
                                ..request.clone()
                            })
                            .unwrap(),
                            &mut Clock {
                                first: true,
                                initial: "2026-10-20T12:00:06Z",
                                publication: "2026-10-20T12:00:06Z",
                            },
                        )
                        .unwrap()
                        .result
                        .work;
                    assert_eq!(reclaimed.planning.as_ref().unwrap().activations, 2);
                    let recovered = store
                        .execute_external(
                            &created.id,
                            "planning.decide",
                            &crate::encode_planning_request(&PlanningRequest {
                                expected_revision: reclaimed.revision,
                                generation: 2,
                                ..decision.clone()
                            })
                            .unwrap(),
                            &mut Clock {
                                first: true,
                                initial: "2026-10-20T12:00:06Z",
                                publication: "2026-10-20T12:00:07Z",
                            },
                        )
                        .unwrap();
                    assert_eq!(recovered.result.work.planning.unwrap().decisions, 1);
                } else {
                    assert_eq!(result.unwrap().result.work.planning.unwrap().decisions, 1);
                }
                store.close().unwrap();
            }
        }
    }
}

GO REFERENCE committed preparation
func (s *Store) configureManagedRepositoryLocked(work string, r ManagedRepositoryRequest) (*ManagedRepository, error) {
	source, err := resolveWorkspace(s.root, r.Path)
	if err != nil {
		return nil, err
	}
	top, err := managedGit(source, "rev-parse", "--show-toplevel")
	if err != nil {
		return nil, err
	}
	subdir, err := filepath.Rel(top, source)
	if err != nil || strings.HasPrefix(subdir, "..") {
		return nil, fmt.Errorf("projet hors dépôt Git")
	}
	if subdir == "." {
		subdir = ""
	}
	encoded, _ := json.Marshal(r)
	digest := hash(encoded)
	storage := filepath.Join(s.root, ".swarm", "managed", work)
	manifest := filepath.Join(storage, "repository.json")
	var retained *ManagedRepository
	var retainedRaw, canonical []byte
	finalPresent := false
	for i, path := range []string{manifest, manifest + ".pending"} {
		raw, err := os.ReadFile(path)
		if os.IsNotExist(err) {
			continue
		}
		if err != nil {
			return nil, err
		}
		var prior ManagedRepository
		if err = json.Unmarshal(raw, &prior); err != nil {
			return nil, fmt.Errorf("manifeste préparé invalide, conservé pour diagnostic : %w", err)
		}
		if err = validatePreparedRepository(prior, storage, source, subdir, digest, r.Include); err != nil {
			return nil, fmt.Errorf("preuve du dépôt préparé conservée sans réécriture : %w", err)
		}
		encoded, err := json.Marshal(prior)
		if err != nil {
			return nil, err
		}
		if retained != nil && string(canonical) != string(encoded) {
			return nil, fmt.Errorf("manifestes final et préparé divergents ; conserver les originaux et réconcilier avant reprise")
		}
		if retained == nil {
			retained, retainedRaw, canonical = &prior, raw, encoded
		}
		finalPresent = finalPresent || i == 0
	}
	if retained != nil {
		if !finalPresent {
			if err = atomicWrite(manifest, retainedRaw); err != nil {
				return nil, err
			}
		}
		return retained, nil
	}
	base, err := managedGit(source, "rev-parse", "HEAD")
	if err != nil {
		return nil, err
	}
	dirty, err := managedGit(source, "status", "--porcelain", "--untracked-files=normal")
	if err != nil {
		return nil, err
	}
	if dirty != "" && !r.CommittedOnly && len(r.Include) == 0 {
		return nil, fmt.Errorf("dépôt modifié : choisir le commit enregistré ou nommer les fichiers de l’instantané")
	}
	if r.CommittedOnly && len(r.Include) > 0 {
		return nil, fmt.Errorf("choisir le commit seul ou une liste de fichiers, pas les deux")
	}
	staging, err := os.MkdirTemp(storage, "repository-build-")
	if err != nil {
		return nil, err
	}
	defer os.RemoveAll(staging)
	bare := filepath.Join(staging, "repository.git")
	if _, err = managedGit(storage, "clone", "--bare", "--no-local", "--no-hardlinks", top, bare); err != nil {
		return nil, err
	}
	included := map[string]string{}
	if len(r.Include) > 0 {
		copyDir := filepath.Join(staging, "snapshot")
		if _, err = managedGit(storage, "clone", "--no-local", bare, copyDir); err != nil {
			return nil, err
		}
		if _, err = managedGit(copyDir, "checkout", "--detach", base); err != nil {
			return nil, err
		}
		total := int64(0)
		for _, name := range r.Include {
			if name == "" || filepath.IsAbs(name) || filepath.Clean(name) != name || name == ".." || strings.HasPrefix(name, "../") || strings.HasPrefix(name, ".git/") || strings.HasPrefix(name, ".swarm/") || name == ".git" || name == ".swarm" {
				return nil, fmt.Errorf("chemin d’instantané interdit : %s", name)
			}
			if _, err = managedGit(source, "check-ignore", "--", name); err == nil {
				return nil, fmt.Errorf("fichier ignoré exclu de l’instantané : %s", name)
			}
			src := filepath.Join(source, name)
			dest := filepath.Join(copyDir, subdir, name)
			for parent := dest; parent != copyDir; parent = filepath.Dir(parent) {
				if st, e := os.Lstat(parent); e == nil && st.Mode()&os.ModeSymlink != 0 {
					return nil, fmt.Errorf("lien interdit dans la destination : %s", name)
				}
			}
			stat, statErr := os.Lstat(src)
			if os.IsNotExist(statErr) {
				if _, err = managedGit(source, "ls-files", "--error-unmatch", "--", name); err != nil {
					return nil, err
				}
				if err = os.Remove(dest); err != nil && !os.IsNotExist(err) {
					return nil, err
				}
				included[name] = "deleted"
				continue
			}
			if statErr != nil || !stat.Mode().IsRegular() {
				return nil, fmt.Errorf("fichier régulier requis : %s", name)
			}
			if _, err = localFile(source, name); err != nil {
				return nil, err
			}
			total += stat.Size()
			if total > 64<<20 {
				return nil, fmt.Errorf("instantané supérieur à 64 Mio")
			}
			data, err := os.ReadFile(src)
			if err != nil {
				return nil, err
			}
			if err = os.MkdirAll(filepath.Dir(dest), 0700); err != nil {
				return nil, err
			}
			if err = os.WriteFile(dest, data, stat.Mode().Perm()); err != nil {
				return nil, err
			}
			included[name] = hash(data)
		}
		gitPaths := []string{}
		for _, name := range r.Include {
			gitPaths = append(gitPaths, filepath.Join(subdir, name))
		}
		if _, err = managedGit(copyDir, append([]string{"add", "-A", "--"}, gitPaths...)...); err != nil {
			return nil, err
		}
		tree, err := managedGit(copyDir, "write-tree")
		if err != nil {
			return nil, err
		}
		base, err = managedGit(copyDir, "commit-tree", tree, "-p", base, "-m", "Instantané autorisé pour Swarm")
		if err != nil {
			return nil, err
		}
		if _, err = managedGit(bare, "fetch", "--no-tags", copyDir, base); err != nil {
			return nil, err
		}
	}
	if _, err = managedGit(bare, "update-ref", "refs/heads/swarm-result", base); err != nil {
		return nil, err
	}
	if _, err = managedGit(bare, "symbolic-ref", "HEAD", "refs/heads/swarm-result"); err != nil {
		return nil, err
	}
	final := filepath.Join(storage, "repository.git")
	if _, err = os.Lstat(final); err == nil {
		return nil, fmt.Errorf("dépôt préparé sans manifeste : examiner avant reprise")
	}
	snap, _ := json.Marshal(map[string]any{"base": base, "files": included})
	repo := &ManagedRepository{Subdir: subdir, Source: source, Storage: storage, Base: base, Candidate: base, Snapshot: hash(snap), Included: r.Include, RequestDigest: digest}
	raw, _ := json.Marshal(repo)
	if err = atomicWrite(manifest+".pending", raw); err != nil {
		return nil, err
	}
	if err = os.Rename(bare, final); err != nil {
		return nil, err
	}
	if err = atomicWrite(manifest, raw); err != nil {
		return nil, err
	}
	return repo, nil
}
func validatePreparedRepository(prior ManagedRepository, storage, source, subdir, digest string, include []string) error {
	if prior.RequestDigest != digest || prior.Storage != storage || prior.Source != source || prior.Subdir != subdir || !slices.Equal(prior.Included, include) {
		return fmt.Errorf("manifeste du dépôt incompatible avec la sélection et ses chemins canoniques ; réconcilier avant reprise")
	}
	snapshot, err := hex.DecodeString(prior.Snapshot)
	if err != nil || len(snapshot) != 32 {
		return fmt.Errorf("empreinte SHA-256 du dépôt préparé absente ou invalide")
	}
	for _, oid := range []string{prior.Base, prior.Candidate} {
		if oid == "" {
			return fmt.Errorf("identité Git du dépôt préparé absente")
		}
		resolved, err := managedGit(filepath.Join(storage, "repository.git"), "rev-parse", "--verify", oid+"^{commit}")
		if err != nil {
			return fmt.Errorf("objet Git préparé absent : %w", err)
		}
		if resolved != oid {
			return fmt.Errorf("identité Git préparée non canonique")
		}
	}
	return nil
}
